(()=>{const m=document.querySelector('.menu-toggle'),n=document.querySelector('#navigation');if(!m||!n)return;const set=o=>{n.classList.toggle('open',o);m.setAttribute('aria-expanded',String(o))};m.addEventListener('click',()=>set(m.getAttribute('aria-expanded')!=='true'));n.addEventListener('click',e=>{if(e.target.closest('a'))set(false)});document.addEventListener('keydown',e=>{if(e.key==='Escape'&&n.classList.contains('open')){set(false);m.focus()}})})();
